export const buildRowsFromMock = () => {
    const rows = [];
    WORK_NAME_MOCK.forEach((section) => {
        section.work_types.forEach((workType) => {
            const workName = section.prefix ? `${section.prefix} ${workType}` : workType;
            rows.push({
                key: `${section.section_type}-${workType}`,
                section_type: section.section_type,
                work_type: workType,
                work_name: workName,
            });
        });
    });
    return rows;
};
export const SECTION_TYPE_OPTIONS = WORK_NAME_MOCK.map((s) => ({
    label: s.section_type,
    value: s.section_type,
}));
export const getWorkTypeOptions = (sectionType) => {
    if (!sectionType)
        return [];
    const section = WORK_NAME_MOCK.find((s) => s.section_type === sectionType);
    return ((section === null || section === void 0 ? void 0 : section.work_types) || []).map((wt) => ({ label: wt, value: wt }));
};
